    /**
     * @var HttpCommonConfig
     */
    protected HttpCommonConfig $httpConfig;

    /**
     * @var bool
     */
    protected bool $init = false;

    /**
     * V3PaymentConfig constructor.
     */
    public function __construct()
    {
        $this->httpConfig = app()->make(HttpCommonConfig::class);
        $this->init();
    }

    /**
     * 初始化
