  `add_way` int(3) NOT NULL DEFAULT '0' COMMENT '该成员添加此客户的来源',
  `oper_userid` varchar(64) NOT NULL DEFAULT '' COMMENT '发起添加的userid，如果成员主动添加，为成员的userid；如果是客户主动添加，则为客户的外部联系人userid；如果是内部成员共享/管理员分配，则为对应的成员/管理员userid',
