#
# Structure for table "eb_work_group_msg_send_result"
#

CREATE TABLE IF NOT EXISTS `eb_work_group_msg_send_result` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `msg_id` varchar(64) NOT NULL DEFAULT '' COMMENT '消息id',
  `external_userid` varchar(64) NOT NULL DEFAULT '' COMMENT '外部联系人userid，群发消息到企业的客户群不返回该字段',
