  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=客户群发，1=客户群群发',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '名称',
  `userids` text NULL DEFAULT NULL COMMENT '成员userid',
  `client_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=全部客户，1=筛选客户',
  `where_time` varchar(100) NOT NULL DEFAULT '' COMMENT '筛选时间',
  `where_label` text NULL DEFAULT NULL COMMENT '筛选标签',
  `where_not_label` text NULL DEFAULT NULL COMMENT '筛选排除标签',
  `template_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=立即发送，1=定时发送',
  `send_time` int(11) NOT NULL DEFAULT '0' COMMENT '定时发送时间',
  `send_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否发送1=已发送，2=正在发送中，0=没有发送',
  `welcome_words` text CHARACTER SET utf8mb4 NULL DEFAULT NULL COMMENT '群发内容',
  `fail_external_userid` text NULL DEFAULT NULL COMMENT '发送失败的客户userid',
