CREATE TABLE IF NOT EXISTS `eb_store_product_rule` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `type` TINYINT(2) NOT NULL DEFAULT '0' COMMENT '商品所属：0：平台1:门店2:供应商',
  `relation_id` INT(10) NOT NULL DEFAULT '0' COMMENT '关联门店、供应商ID',
  `rule_name` varchar(32) NOT NULL DEFAULT '' COMMENT '规格名称',
  `rule_value` text NULL DEFAULT NULL COMMENT '规格值',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COMMENT='商品规则值(规格)表';

