      KEY `staff_id` (`staff_id`) USING BTREE,
      KEY `type` (`type`) USING BTREE,
      KEY `add_time` (`add_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='门店资金流水表';


