      "raw_utf8": "<template>
	<!-- 手机号登录弹窗 -->
	<view v-if="isUp">
		<view class="mobile-bg" @click="close"></view>
		<view class="mobile-mask animated" :class="{slideInUp:isUp}">
			<view class="input-item">
				<input type="text" v-model="account" placeholder="输入手机号" maxlength="11" />
			</view>
			<view class="input-item">
				<input type="text" v-model="codeNum" placeholder="输入验证码" maxlength="6" />
				<button class="code" :disabled="disabled" @click="code">{{text}}</button>
			</view>
			<view class="sub_btn" @click="loginBtn">立即登录</view>
		</view>
		<Verify @success="success" :captchaType="'blockPuzzle'" :imgSize="{ width: '330px', height: '155px' }"
			ref="verify"></Verify>
	</view>
</template>

<script>
	const app = getApp();
	import sendVerifyCode from "@/mixins/SendVerifyCode";
	import Routine from '@/libs/routine';
	import Verify from '../verify/verify.vue';
	import {
		loginMobile,
		registerVerify,
		getCodeApi,
		getUserInfo,
		phoneSilenceAuth,
		phoneWxSilenceAuth
	} from "@/api/user";
	import {
		bindingPhone
	} from '@/api/api.js'
	export default {
		name: 'login_mobile',
		components: {
			Verify
		},
		props: {
			isUp: {
				type: Boolean,
				default: false,
			},
			authKey: {
				type: String,
				default: '',
			}
		},
		data() {
			return {
				keyCode: '',
				account: '',
				codeNum: ''
			}
		},
		mixins: [sendVerifyCode],
		mounted() {
			this.getCode();
		},
		methods: {
			success(data) {
				let that = this;
				this.$refs.verify.hide()
				getCodeApi().then(res => {
					registerVerify({
						phone: that.account,
						key: res.data.key,
						captchaType: 'blockPuzzle',
						captchaVerification: data.captchaVerification
					}).then(res => {
						that.$util.Tips({
							title: res.msg
						});
						that.sendCode();
					}).catch(err => {
						return that.$util.Tips({
							title: err
						})
					})
				})
			},
			// 获取验证码
			code() {
				let that = this;
				if (!that.account) return that.$util.Tips({
					title: '请填写手机号码'
				});
				if (!/^1(3|4|5|7|8|9|6)\d{9}$/i.test(that.account)) return that.$util.Tips({
					title: '请输入正确的手机号码'
				});
				// await registerVerify({
				// 	phone: that.account,
