  const { systemConfig } = await import("@/models/schema");
  const rows = await container.db
    .select()
    .from(systemConfig)
    .where(sql`${systemConfig.menuName} LIKE 'sms_%' OR ${systemConfig.menuName} LIKE 'notice_%'`);
  const config: Record<string, string> = {};
  for (const r of rows) {
    config[r.menuName] = r.value ?? "";
  }
  return jsonOk(c, config);
}

/** POST /api/admin/sms/config — 短信配置保存 */
export async function adminSmsConfigSave(c: C) {
  const body = await c.req.json().catch(() => ({}));
  // This legacy handler accepts arbitrary keys. Reject the entire controlled
  // domain before its first SQL write, including a mixed ordinary batch.
  if (Object.keys(body ?? {}).some(isCityConfigKey)) throw new ValidateException('同城配送配置只能通过专用版本化接口保存');
  if (Object.keys(body ?? {}).some(isPcBaseConfigKey)) throw new ValidateException('PC配置只能通过专用版本化接口保存');
  if (Object.keys(body ?? {}).some(isWechatOpenConfigKey)) throw new ValidateException('开放平台配置只能通过专用版本化接口保存');
  if (Object.keys(body ?? {}).some(isWechatBaseConfigKey)) throw new ValidateException('公众号基础配置只能通过专用版本化接口保存');
  const container = c.get("container");
  const { eq } = await import("drizzle-orm");
  const { systemConfig } = await import("@/models/schema");
  for (const [key, value] of Object.entries(body)) {
    const existing = await container.db
      .select()
      .from(systemConfig)
      .where(eq(systemConfig.menuName, key))
      .limit(1);
    if (existing.length) {
      await container.db
        .update(systemConfig)
        .set({ value: String(value) })
        .where(eq(systemConfig.menuName, key));
    } else {
      await container.db.insert(systemConfig).values({
        menuName: key,
        info: key,
        value: String(value),
        isStore: 0,
        type: "input",
        inputType: "input",
        sort: 0,
        status: 1,
      });
    }
  }
  return jsonOk(c, null, "保存成功");
}

