import { sql } from 'drizzle-orm';
import type { DbClient } from '../lib/di';
/** Explicit fixed gift catalog. No runtime DDL, grants or drift repair. */
export const ORDER_PROMOTION_GIFT_RECEIPT_DDL = `
CREATE TABLE public.store_order_promotion_gift_coupon_reward (
      id SERIAL PRIMARY KEY, order_id INTEGER NOT NULL, uid INTEGER NOT NULL,
      root_id INTEGER NOT NULL, tier_id INTEGER NOT NULL, auxiliary_id INTEGER NOT NULL,
      issue_coupon_id INTEGER NOT NULL, coupon_user_id INTEGER NOT NULL,
      add_time INTEGER DEFAULT 0 NOT NULL,
      CONSTRAINT sopgcr_positive_ids_ck CHECK (order_id>0 AND uid>0 AND root_id>0
        AND tier_id>0 AND auxiliary_id>0 AND issue_coupon_id>0 AND coupon_user_id>0 AND add_time>=0)
    );
    CREATE UNIQUE INDEX sopgcr_order_aux_uq ON public.store_order_promotion_gift_coupon_reward(order_id,auxiliary_id);
    CREATE UNIQUE INDEX sopgcr_coupon_user_uq ON public.store_order_promotion_gift_coupon_reward(coupon_user_id);
    CREATE INDEX sopgcr_uid_order ON public.store_order_promotion_gift_coupon_reward(uid,order_id,id);
REVOKE ALL ON public.store_order_promotion_gift_coupon_reward FROM PUBLIC;
REVOKE ALL ON SEQUENCE public.store_order_promotion_gift_coupon_reward_id_seq FROM PUBLIC;
`;
const literal=(value:string|null)=>value===null?'NULL':"'"+value.replaceAll("'","''")+"'";
const t='store_order_promotion_gift_coupon_reward';
const columnSpec=[
 [t,'id','integer',"nextval('store_order_promotion_gift_coupon_reward_id_seq'::regclass)"],
 ...['order_id','uid','root_id','tier_id','auxiliary_id','issue_coupon_id','coupon_user_id'].map(n=>[t,n,'integer',null] as const),
 [t,'add_time','integer','0'],
] as const;
const constraintSpec=[
 [t,t+'_pkey','PRIMARY KEY (id)'],
 [t,'sopgcr_positive_ids_ck','CHECK (((order_id > 0) AND (uid > 0) AND (root_id > 0) AND (tier_id > 0) AND (auxiliary_id > 0) AND (issue_coupon_id > 0) AND (coupon_user_id > 0) AND (add_time >= 0)))'],
] as const;
const indexSpec=[
 [t,t+'_pkey','CREATE UNIQUE INDEX '+t+'_pkey ON public.'+t+' USING btree (id)'],
 [t,'sopgcr_order_aux_uq','CREATE UNIQUE INDEX sopgcr_order_aux_uq ON public.'+t+' USING btree (order_id, auxiliary_id)'],
 [t,'sopgcr_coupon_user_uq','CREATE UNIQUE INDEX sopgcr_coupon_user_uq ON public.'+t+' USING btree (coupon_user_id)'],
 [t,'sopgcr_uid_order','CREATE INDEX sopgcr_uid_order ON public.'+t+' USING btree (uid, order_id, id)'],
] as const;
export const ORDER_PROMOTION_GIFT_CATALOG_INSPECTION_SQL = `WITH expected_columns(table_name,column_name,type_name,default_expr) AS (VALUES
${columnSpec.map(row => '(' + row.map(literal).join(',') + ')').join(',\n')}
), expected_constraints(table_name,name,definition) AS (VALUES
