    candidate.matches.some((matcher) => matchesRoute(route, matcher)),
  );
  if (!group) return null;
  if (
    group.key === "live_broadcast"
    && (
      new Set([
        "live/room/syncroom",
        "live/goods/syncgoods",
        "live/anchor/syncanchor",
      ]).has(route)
      || /^live\/(?:room|goods|anchor)\/set_show\/[^/]+\/[^/]+$/.test(route)
