import {createHash} from 'node:crypto';
import {readRulePredecessor as readFileSync} from './helpers/pcBaseAuthorSourceBinding';
import {resolve} from 'node:path';
import {describe,expect,it} from 'vitest';
import {buildRulePredecessorApiAuditReport as buildAdminFrontendApiAuditReport} from './helpers/pcBaseAuthorSourceBinding';
import {ensureSourceBinding as proof,reverseEnsureSource,readEnsurePredecessor,readUnitPredecessor,unitSourceBinding,reverseUnitSource,buildEnsurePredecessorApiAuditReport} from './helpers/pcBaseAuthorSourceBinding';
import {ENSURE_FIELDS,ensureName,ensureDescription,ensureSort,ensureImage,ensureAction,ensureReceipt,ensureCatalog,type EnsureAction} from '../../view/common/ensureAuthor';
const root=resolve(import.meta.dirname,'../..'),read=(file:string)=>readFileSync(resolve(root,file),'utf8');
const sha=(value:string|Uint8Array)=>createHash('sha256').update(value).digest('hex');
const stripImports=(value:string)=>value.replace(/^import[\s\S]*?;\n/gmu,'');
const row=(extra={})=>({id:1,type:0,relation_id:0,name:'',image:'http://old.invalid/raw',desc:'',sort:-2147483648,status:-1,add_time:0,product_count:0,image_preview:'',...extra});
const action=(operation:EnsureAction['operation']='update'):EnsureAction=>({operation_id:'40000000-0000-4000-8000-000000000001',actor_id:1,operation,target_id:operation==='create'?0:1,revision:'a'.repeat(64),payload:operation==='delete'?{}:operation==='status'?{status:0}:{name:'条款',image:'/api/assets/1',desc:'描述',sort:0},payload_hash:'b'.repeat(64)});
describe('Ensure exact immutable increment and fixed PHP contract sources, not runtime acceptance',()=>{
 for(const source of proof.sources){
  it('pins complete current and pre-Ensure bytes '+source.file,()=>{const raw=read(source.file);expect(sha(raw)).toBe(source.after_sha256);expect(sha(reverseEnsureSource(source.file,raw))).toBe(source.before_sha256);expect(sha(readEnsurePredecessor(resolve(root,source.file)))).toBe(source.before_sha256);});
  it('rejects drift and forged whole-source inverses '+source.file,()=>{const raw=read(source.file);for(const bad of[raw.slice(1),raw+'\n// unreviewed\n',raw+raw])expect(()=>reverseEnsureSource(source.file,bad)).toThrow();for(const key of ['before_sha256','after_sha256']as const){const forged=structuredClone(proof);forged.sources.find(r=>r.file===source.file)![key]='0'.repeat(64);expect(()=>reverseEnsureSource(source.file,raw,forged)).toThrow();}const forged=structuredClone(proof);forged.sources.find(r=>r.file===source.file)!.edits[0]!.after_line=2;expect(()=>reverseEnsureSource(source.file,raw,forged)).toThrow();});
  if(proof.predecessor_readports.includes(source.file))it('keeps every predecessor assertion and negative fixture exact '+source.file,()=>expect(stripImports(source.edits[0]!.after_source)).toBe(stripImports(source.edits[0]!.before_source)));
 }
 for(const source of proof.full_additions)it('pins full addition '+source.file,()=>{const raw=readFileSync(resolve(root,source.file));expect(raw.length).toBe(source.bytes);expect(sha(raw)).toBe(source.sha256);});
 for(const source of proof.PHP_sources)it('pins complete fixed PHP original '+source.file,()=>{expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');expect(sha(source.raw_utf8)).toBe(source.sha256);expect(Buffer.byteLength(source.raw_utf8)).toBe(source.bytes);});
 const frozen=Object.entries(proof.frozen_predecessor_evidence);
 for(let i=0;i<frozen.length;i+=64)it(`preserves accepted predecessor evidence ${i+1}..${Math.min(i+64,frozen.length)}`,()=>{for(const[file,hash]of frozen.slice(i,i+64))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});
 it('pins original recommendation PNG without inventing a second image slot',()=>{const assets=(proof as typeof proof & {PHP_assets:Array<{file:string;bytes:number;sha256:string;base64:string}>}).PHP_assets;expect(assets).toHaveLength(1);const raw=Buffer.from(assets[0]!.base64,'base64');expect(raw.length).toBe(assets[0]!.bytes);expect(sha(raw)).toBe(assets[0]!.sha256);expect(assets[0]!.file).toBe('public/statics/system/productEnsure.png');});
 it('pins real7905 before image and leaves accepted Unit proof/helper/document immutable',()=>{expect(proof.baseline.file_count).toBe(7905);expect(proof.predecessor_readports).toHaveLength(29);for(const file of['workers-ts/audit/product-unit-author-source-binding-20261026.json','workers-ts/test/helpers/unitSourceBinding.ts','workers-ts/docs/php-ts-product-unit-author-20261026.md']){expect(proof.sources.some(s=>s.file===file)).toBe(false);expect(sha(read(file))).toBe(proof.frozen_predecessor_evidence[file]);}});
 it('composes exact Ensure then Unit before all earlier source layers',()=>{for(const file of['workers-ts/src/routes/adminapi.ts','workers-ts/src/routes/v1/index.ts']){const before=reverseEnsureSource(file,read(file));expect(readEnsurePredecessor(resolve(root,file),'utf8')).toBe(before);expect(readUnitPredecessor(resolve(root,file),'utf8')).toBe(reverseUnitSource(file,before));}expect(reverseEnsureSource('unrelated.ts','unchanged')).toBe('unchanged');expect(sha(proof.previous_report.raw_utf8)).toBe(unitSourceBinding.current_report.sha256);});
 it('keeps all mature Ensure, binding/public/media consumers and runtime plan unchanged',()=>{for(const[file,hash]of Object.entries(proof.observed_unchanged))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);for(const file of['workers-ts/src/services/admin/AdminProductEnsureService.ts','workers-ts/src/services/product/ProductExperienceService.ts','workers-ts/src/services/product/ProductAssociationService.ts','workers-ts/src/services/supplier/SupplierProductManagementService.ts','workers-ts/src/services/supplier/SupplierProductEnsureBindings.ts','workers-ts/src/migrations/runtimeBusinessPrivilegePlan.ts'])expect(Object.hasOwn(proof.observed_unchanged,file)).toBe(true);});
 it('rebuilds real inventory, retains all801 old variant records and adds only six Ensure wrappers',()=>{const current=buildAdminFrontendApiAuditReport(),before=buildEnsurePredecessorApiAuditReport();expect(JSON.stringify(current,null,2)+'\n').toBe(read(proof.current_report.file));expect(before.counts.callSites).toBe(763);expect(before.counts.pathVariants).toBe(801);expect(current.counts).toEqual({callSites:769,pathVariants:807,registered:807,executable:807,controlledUnavailable:0,unregistered:0,unresolved:0});for(const call of before.calls)expect(current.calls).toContainEqual(call);expect(current.calls.filter(c=>c.source==='view/admin-ts/src/api/ensureAuthor.ts')).toHaveLength(6);expect(proof.retired_api_calls).toEqual([]);});
 it('maintains only the actual parent Ensure transport while keeping all other Unit cases exact',()=>{
  type Maintenance={cases:Array<{before_source:string;after_source:string;before_sha256:string;after_sha256:string}>;files:Array<{path:string;before_source:string;after_source:string;before_sha256:string;after_sha256:string}>};
  const m=(proof as typeof proof & {frontend_test_maintenance:Maintenance}).frontend_test_maintenance;
  expect(m.cases).toHaveLength(3);for(const c of m.cases){expect(sha(c.before_source)).toBe(c.before_sha256);expect(sha(c.after_source)).toBe(c.after_sha256);}
  expect(m.cases[0]!.after_source).toBe(m.cases[0]!.before_source.replace("['保障服务','/ensure']","['保障服务','/product/ensure/author/catalog']"));for(const c of m.cases.slice(1))expect(c.after_source).toBe(c.before_source);
  for(const f of m.files){expect(sha(read(f.path))).toBe(f.after_sha256);expect(sha(f.before_source)).toBe(f.before_sha256);expect(read(f.path)).toBe(f.after_source);}
  const suite=m.files.find(f=>f.path.endsWith('/unit-author-page-runtime.test.cjs'))!;expect(suite.after_source.replace(m.cases[0]!.after_source,m.cases[0]!.before_source)).toBe(suite.before_source);
 });
 it('extends only the exact Ensure owner route family inside old permission test',()=>{const e=proof.permission_test_extension,source=proof.sources.find(s=>s.file===e.file)!.edits[0]!;expect(source.after_source.replace(e.added_source,'').replace('  isAdminEnsureRecoveryRoute,\n','')).toBe(source.before_source);expect(e.unchanged_case_count).toBe(24);});
 it('binds original routed nine-column list,15/page and four-value form100 with separate set_show',()=>{const php=(file:string)=>proof.PHP_sources.find(s=>s.file===file)!.raw_utf8,view=php('view/admin/src/pages/product/ensure/index.vue'),service=php('app/services/product/ensure/StoreProductEnsureServices.php');for(const key of['id','name','product_count','sort','add_time'])expect(view).toContain(`key: "${key}"`);for(const slot of['image','desc','status','action'])expect(view).toContain(`slot: "${slot}"`);expect(view).toContain('limit: 15');expect(service).toContain('maxlength(100)');expect(service).toContain("Form::frameImage('image'");expect(ENSURE_FIELDS).toEqual(['name','image','desc','sort']);});
 it('preserves same historical255 names empty desc negative int32 and unsafe raw image without creating new media permission',()=>{for(const value of['','😀'.repeat(255),' old\u0085 '])expect(ensureName(value,value)).toBe(value);expect(ensureDescription('','')).toBe('');expect(ensureSort(-2147483648,-2147483648)).toBe(-2147483648);expect(ensureImage('http://old.invalid/x','http://old.invalid/x')).toBe('http://old.invalid/x');for(const value of['','😀'.repeat(101),'x\n','x\ud800'])expect(()=>ensureName(value)).toThrow();for(const value of[-1,2147483648,'01',1.5,null])expect(()=>ensureSort(value)).toThrow();});
 it('keeps four-field saves distinct from status/delete and binds original action owner/target',()=>{expect(ensureAction(action(),1)).toEqual(action());expect(ensureAction(action('status'),1).payload).toEqual({status:0});for(const extra of[{status:1},{is_del:1},{product_count:0},{type:2}])expect(()=>ensureAction({...action(),payload:{...action().payload,...extra}},1)).toThrow();expect(()=>ensureAction(action(),2)).toThrow();expect(()=>ensureAction({...action('status'),payload:{status:2}},1)).toThrow();});
 it('requires complete all-platform catalog without hiding disabled or unknown statuses',()=>{const c={list:[row()],count:1,revision:'a'.repeat(64),write_ready:true,can_create:true};expect(ensureCatalog(c)).toEqual(c);for(const patch of[{count:2},{list:[row(),row()],count:2},{list:[row({type:2})]},{list:[row({relation_id:7})]},{list:[row({is_del:0})]},{list:[row({image_preview:'javascript:bad'})]}])expect(()=>ensureCatalog({...c,...patch})).toThrow();});
 it('requires strict original terminal receipts while missing is not terminal evidence',()=>{const a=action(),{payload:_,...metadata}=a,result={id:1,created:0,updated:1,count:3,revision:'c'.repeat(64)};expect(ensureReceipt({...metadata,state:'committed',result},a).state).toBe('committed');for(const patch of[{id:2},{updated:0},{created:1}])expect(()=>ensureReceipt({...metadata,state:'committed',result:{...result,...patch}},a)).toThrow();expect(()=>ensureReceipt({...metadata,state:'missing',result},a)).toThrow();});
});

