 for(const source of proof.sources){
  it('pins complete current and accepted Hotword bytes '+source.file,()=>{const raw=read(source.file);expect(sha(raw)).toBe(source.after_sha256);expect(sha(reverseProductLabelAuthorSource(source.file,raw))).toBe(source.before_sha256);expect(sha(readProductLabelAuthorPredecessor(resolve(root,source.file)))).toBe(source.before_sha256);});
