 }
 for(const file of proof.full_additions)it('pins complete new file without claiming it is predecessor '+file.file,()=>{const raw=readFileSync(resolve(root,file.file));expect(raw.byteLength).toBe(file.bytes);expect(sha(raw)).toBe(file.sha256);expect(proof.sources.some(row=>row.file===file.file)).toBe(false);});
 for(const file of proof.PHP_sources)it('binds full fixed PHP blob '+file.file,()=>{expect(Buffer.byteLength(file.raw_utf8)).toBe(file.bytes);expect(sha(file.raw_utf8)).toBe(file.sha256);expect(file.git_blob).toMatch(/^[a-f0-9]{40}$/u);expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');});
 const frozen=Object.entries(proof.frozen_predecessor_evidence);for(let i=0;i<frozen.length;i+=64)it('retains all immutable predecessor evidence bytes chunk '+i,()=>{for(const[file,hash]of frozen.slice(i,i+64))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});

 // Exactly24 fixed semantic cases, alongside the dynamic whole-byte cases.
 it('partitions the true8000 before,1733 frozen evidence and33 old ports without publishing outputs as changes',()=>{expect(proof.baseline.file_count).toBe(8000);expect(frozen).toHaveLength(1733);expect(proof.predecessor_readports).toHaveLength(33);expect(new Set(proof.sources.map(row=>row.file)).size).toBe(proof.sources.length);expect(new Set(proof.full_additions.map(row=>row.file)).size).toBe(proof.full_additions.length);for(const file of['workers-ts/audit/product-hotword-author-source-binding-20261027.json','workers-ts/test/helpers/hotwordSourceBinding.ts','workers-ts/docs/php-ts-product-hotword-author-20261027.md']){expect(proof.sources.some(row=>row.file===file)).toBe(false);expect(sha(read(file))).toBe(proof.frozen_predecessor_evidence[file]);}});
