 it('maps both complete accepted Hotword ledgers to physical validation images and the immutable inner bridges',()=>{expect(proof.predecessor_publication.map(row=>row.file).sort()).toEqual(['MIGRATION_AUDIT.md','MIGRATION_CHECKLIST.md']);for(const bridge of proof.predecessor_publication){expect(read(bridge.file)).toBe(bridge.accepted_source);expect(sha(bridge.accepted_source)).toBe(bridge.accepted_sha256);expect(sha(bridge.validation_source)).toBe(bridge.validation_sha256);expect(reverseProductLabelAuthorPredecessorPublication(bridge.file,bridge.accepted_source)).toBe(bridge.validation_source);expect(readProductLabelAuthorPredecessor(resolve(root,bridge.file),'utf8')).toBe(bridge.validation_source);const inner=hotwordSourceBinding.predecessor_publication.find(row=>row.file===bridge.file)!;expect(bridge.validation_source).toBe(inner.accepted_source);const parameterImage=reverseHotwordPredecessorPublication(bridge.file,bridge.validation_source);expect(readHotwordPredecessor(resolve(root,bridge.file),'utf8')).toBe(parameterImage);expect(parameterImage).toBe(parameterSourceBinding.predecessor_publication.find(row=>row.file===bridge.file)!.accepted_source);expect(readParameterPredecessor(resolve(root,bridge.file),'utf8')).toBe(reverseParameterPredecessorPublication(bridge.file,parameterImage));}});
 it('binds five full physical origins and accepted receipt instead of fabricating a ledger prefix',()=>{const records=proof.predecessor_publication_origins;expect(Object.keys(records).sort()).toEqual(['hotword_accepted_manifest','hotword_before_manifest','hotword_receipt','hotword_validation_manifest','product_label_before_manifest']);for(const value of Object.values(records)){expect(sha(value.raw_utf8)).toBe(value.sha256);expect(value.file.startsWith('/')).toBe(true);}const receipt=JSON.parse(records.hotword_receipt!.raw_utf8);expect(receipt.status).toBe('accepted');expect(receipt.input_files).toBe(8000);expect(receipt.source_proof_sha256).toBe(sha(read('workers-ts/audit/product-hotword-author-source-binding-20261027.json')));expect(records.hotword_validation_manifest!.sha256).toBe(receipt.current_source_manifest_sha256);expect(records.hotword_before_manifest!.sha256).toBe(receipt.before_manifest_sha256);expect(records.hotword_accepted_manifest!.sha256).toBe(receipt.input_manifest_sha256);expect(records.product_label_before_manifest!.sha256).toBe(proof.baseline.sha256);expect(records.product_label_before_manifest!.raw_utf8).toBe(records.hotword_accepted_manifest!.raw_utf8);for(const bridge of proof.predecessor_publication){for(const key of['hotword_validation_manifest','hotword_before_manifest']){const row=(JSON.parse(records[key]!.raw_utf8)as Array<{path:string;sha256:string;bytes:number}>).find(row=>row.path===bridge.file)!;expect(row.sha256).toBe(bridge.validation_sha256);expect(row.bytes).toBe(Buffer.byteLength(bridge.validation_source));}for(const key of['hotword_accepted_manifest','product_label_before_manifest']){const row=(JSON.parse(records[key]!.raw_utf8)as Array<{path:string;sha256:string;bytes:number}>).find(row=>row.path===bridge.file)!;expect(row.sha256).toBe(bridge.accepted_sha256);expect(row.bytes).toBe(Buffer.byteLength(bridge.accepted_source));}expect(bridge.validation_origin).toContain('/parameter-author-20261026/inputs/');expect(bridge.accepted_origin).toContain('/hotword-author-20261027/inputs/');}});
