import {createHash} from 'node:crypto';
import {readParameterPredecessor as readFileSync} from './helpers/pcBaseAuthorSourceBinding';
import {resolve} from 'node:path';
import {describe,expect,it} from 'vitest';
import {buildParameterPredecessorApiAuditReport as buildAdminFrontendApiAuditReport} from './helpers/pcBaseAuthorSourceBinding';
import {ruleSourceBinding as proof,reverseRuleSource,reverseRulePredecessorPublication,readRulePredecessor,readEnsurePredecessor,ensureSourceBinding,reverseEnsureSource,buildRulePredecessorApiAuditReport} from './helpers/pcBaseAuthorSourceBinding';
import {ruleName,ruleSpec,ruleProjection,ruleAction,ruleReceipt,ruleCatalog,type RuleAction} from '../../view/common/ruleAuthor';
const root=resolve(import.meta.dirname,'../..'),read=(file:string)=>readFileSync(resolve(root,file),'utf8');
const sha=(value:string|Uint8Array)=>createHash('sha256').update(value).digest('hex');
const stripImports=(value:string)=>value.replace(/^import[\s\S]*?;\n/gmu,'');
const row=(extra={})=>({id:1,type:0,relation_id:0,rule_name:'',rule_value:null,...extra});
const action=(operation:RuleAction['operation']='update'):RuleAction=>({operation_id:'40000000-0000-4000-8000-000000000001',actor_id:1,operation,target_id:operation==='create'?0:1,revision:'a'.repeat(64),payload:operation==='delete'?{}:{rule_name:'模板',mode:'preserve'},payload_hash:'b'.repeat(64)});
describe('Rule exact increment and fixed PHP contract lineage; distinct from runtime acceptance',()=>{
 for(const source of proof.sources){
  it('pins complete current and pre-Rule bytes '+source.file,()=>{const raw=read(source.file);expect(sha(raw)).toBe(source.after_sha256);expect(sha(reverseRuleSource(source.file,raw))).toBe(source.before_sha256);expect(sha(readRulePredecessor(resolve(root,source.file)))).toBe(source.before_sha256);});
  it('rejects drift and forged exact-source inverse '+source.file,()=>{const raw=read(source.file);for(const bad of[raw.slice(1),raw+'\n// unreviewed\n',raw+raw])expect(()=>reverseRuleSource(source.file,bad)).toThrow();for(const key of['before_sha256','after_sha256']as const){const forged=structuredClone(proof);forged.sources.find(r=>r.file===source.file)![key]='0'.repeat(64);expect(()=>reverseRuleSource(source.file,raw,forged)).toThrow();}const forged=structuredClone(proof);forged.sources.find(r=>r.file===source.file)!.edits[0]!.after_line=2;expect(()=>reverseRuleSource(source.file,raw,forged)).toThrow();});
  if(proof.predecessor_readports.includes(source.file))it('preserves every old case and negative fixture '+source.file,()=>expect(stripImports(source.edits[0]!.after_source)).toBe(stripImports(source.edits[0]!.before_source)));
 }
 for(const source of proof.full_additions)it('pins full addition '+source.file,()=>{const raw=readFileSync(resolve(root,source.file));expect(raw.length).toBe(source.bytes);expect(sha(raw)).toBe(source.sha256);});
 for(const source of proof.PHP_sources)it('pins whole fixed PHP original '+source.file,()=>{expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');expect(sha(source.raw_utf8)).toBe(source.sha256);expect(Buffer.byteLength(source.raw_utf8)).toBe(source.bytes);});
 const frozen=Object.entries(proof.frozen_predecessor_evidence);
 for(let i=0;i<frozen.length;i+=64)it(`preserves immutable predecessor evidence ${i+1}..${Math.min(i+64,frozen.length)}`,()=>{for(const[file,hash]of frozen.slice(i,i+64))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});
 it('uses the actual7929 accepted Ensure image and leaves proof/helper/document immutable',()=>{expect(proof.baseline.file_count).toBe(7929);expect(proof.predecessor_readports).toHaveLength(30);expect(frozen).toHaveLength(1724);for(const file of['workers-ts/audit/product-ensure-author-source-binding-20261026.json','workers-ts/test/helpers/ensureSourceBinding.ts','workers-ts/docs/php-ts-product-ensure-author-20261026.md']){expect(proof.sources.some(s=>s.file===file)).toBe(false);expect(sha(read(file))).toBe(proof.frozen_predecessor_evidence[file]);}});
 it('composes exact Rule then Ensure before all earlier source layers',()=>{for(const file of['workers-ts/src/routes/adminapi.ts','workers-ts/src/routes/v1/index.ts']){const before=reverseRuleSource(file,read(file));expect(readRulePredecessor(resolve(root,file),'utf8')).toBe(before);expect(readEnsurePredecessor(resolve(root,file),'utf8')).toBe(reverseEnsureSource(file,before));}expect(reverseRuleSource('unrelated.ts','unchanged')).toBe('unchanged');expect(sha(proof.previous_report.raw_utf8)).toBe(ensureSourceBinding.current_report.sha256);});
 it('binds the complete predecessor publication append to its actual immutable ledger validation image',()=>{expect(proof.predecessor_publication.map(row=>row.file).sort()).toEqual(['MIGRATION_AUDIT.md','MIGRATION_CHECKLIST.md']);for(const row of proof.predecessor_publication){expect(read(row.file)).toBe(row.accepted_source);expect(sha(row.accepted_source)).toBe(row.accepted_sha256);expect(sha(row.validation_source)).toBe(row.validation_sha256);expect(ensureSourceBinding.observed_unchanged[row.file]).toBe(row.validation_sha256);expect(reverseRulePredecessorPublication(row.file,row.accepted_source)).toBe(row.validation_source);expect(readRulePredecessor(resolve(root,row.file),'utf8')).toBe(row.validation_source);for(const raw of[row.accepted_source+'\n',row.accepted_source.slice(1),row.validation_source])expect(()=>reverseRulePredecessorPublication(row.file,raw)).toThrow();const forged=structuredClone(proof);forged.predecessor_publication.find(item=>item.file===row.file)!.validation_sha256='0'.repeat(64);expect(()=>reverseRulePredecessorPublication(row.file,row.accepted_source,forged)).toThrow();}});
 it('keeps all mature rule, product-copy, Supplier and runtime privilege-plan code exact',()=>{for(const[file,hash]of Object.entries(proof.observed_unchanged))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);for(const file of['workers-ts/src/services/admin/AdminProductRuleService.ts','workers-ts/src/services/product/ProductMetadataService.ts','workers-ts/src/services/product/ProductAssociationService.ts','workers-ts/src/services/supplier/SupplierProductRuleService.ts','workers-ts/src/services/supplier/SupplierProductRuleInput.ts','workers-ts/src/migrations/runtimeBusinessPrivilegePlan.ts'])expect(Object.hasOwn(proof.observed_unchanged,file)).toBe(true);});
 it('extends the exhaustive permission catalog with exactly four Rule recovery routes while preserving all old cases',()=>{type M={path:string;before_source:string;after_source:string;before_sha256:string;after_sha256:string;added_import:string;added_contract:string};const m=(proof as typeof proof&{permission_test_extension:M}).permission_test_extension;expect(read(m.path)).toBe(m.after_source);expect(sha(m.before_source)).toBe(m.before_sha256);expect(sha(m.after_source)).toBe(m.after_sha256);expect(m.after_source.replace(m.added_import,'').replace(m.added_contract,'')).toBe(m.before_source);expect(m.added_contract).toContain('isAdminRuleRecoveryRoute');expect(m.added_contract).toContain('/product/rule/author/receipt/:operationId');expect(m.added_contract).toContain('/product/rule/author/resolve');});
 it('rebuilds actual API773/811 and retains all807 predecessor variant objects',()=>{const current=buildAdminFrontendApiAuditReport(),before=buildRulePredecessorApiAuditReport();expect(JSON.stringify(current,null,2)+'\n').toBe(read(proof.current_report.file));expect(before.counts.callSites).toBe(769);expect(before.counts.pathVariants).toBe(807);expect(current.counts).toEqual({callSites:773,pathVariants:811,registered:811,executable:811,controlledUnavailable:0,unregistered:0,unresolved:0});for(const call of before.calls)expect(current.calls).toContainEqual(call);expect(current.calls.filter(call=>call.source==='view/admin-ts/src/api/ruleAuthor.ts')).toHaveLength(4);expect(proof.retired_api_calls).toEqual([]);});
 it('maintains one actual Unit-parent Rule URL without rewriting its other two cases',()=>{
  type M={cases:Array<{before_source:string;after_source:string;before_sha256:string;after_sha256:string}>;files:Array<{path:string;before_source:string;after_source:string;before_sha256:string;after_sha256:string}>};const m=(proof as typeof proof&{frontend_test_maintenance:M}).frontend_test_maintenance;
  expect(m.cases).toHaveLength(3);for(const c of m.cases){expect(sha(c.before_source)).toBe(c.before_sha256);expect(sha(c.after_source)).toBe(c.after_sha256);}expect(m.cases[0]!.after_source).toBe(m.cases[0]!.before_source.replace("['SKU 规格模板','/product/rule']","['SKU 规格模板','/product/rule/author/catalog']"));for(const c of m.cases.slice(1))expect(c.after_source).toBe(c.before_source);
  for(const f of m.files){expect(read(f.path)).toBe(f.after_source);expect(sha(f.before_source)).toBe(f.before_sha256);expect(sha(f.after_source)).toBe(f.after_sha256);}const suite=m.files.find(f=>f.path.endsWith('/unit-author-page-runtime.test.cjs'))!;expect(suite.after_source.replace(m.cases[0]!.after_source,m.cases[0]!.before_source)).toBe(suite.before_source);
 });
 it('binds actual product_attr route and raw five-column storage without invented fields',()=>{const php=(suffix:string)=>proof.PHP_sources.find(item=>item.file.endsWith(suffix))!.raw_utf8;expect(php('router/modules/product.js')).toContain('product_attr');expect(php('product/productAttr/index.vue')).toContain('limit: 10');const service=read('workers-ts/src/services/admin/AdminRuleAuthorService.ts');expect(service).toContain('pg_advisory_xact_lock(731612,0)');expect(service).toContain('pg_advisory_xact_lock(731648,1)');expect(service).toContain('SET CONSTRAINTS ALL IMMEDIATE');expect(service).not.toMatch(/product_count|isDel|\.from\(storeProduct\)/);});
 it('keeps invalid raw JSON distinct from a writable display projection',()=>{for(const raw of[null,'','0','null','{}','false','[]','{bad','[{"value":"a","detail":["x"],"unknown":true}]']){expect(ruleCatalog({list:[row({rule_value:raw})],count:1,revision:'a'.repeat(64),write_ready:true,can_create:true}).list[0]!.rule_value).toBe(raw);expect(ruleProjection(raw).spec).toBeNull();}const raw=' [ { "detail": [" x "], "value": " a " } ] ';expect(ruleProjection(raw).spec).toEqual([{value:' a ',detail:[' x ']}]);});
 it('keeps modern32/32/64 Unicode and full batches instead of PHP UI20/30 or silent dedup',()=>{expect(ruleName('😀'.repeat(32))).toBe('😀'.repeat(32));expect(ruleSpec([{value:'😀'.repeat(32),detail:['🧭'.repeat(64)]}])).toHaveLength(1);for(const spec of[[],[{value:'a',detail:['x',' x ']}],[{value:'a',detail:['x'],unknown:1}]])expect(()=>ruleSpec(spec)).toThrow();expect(ruleName('','')).toBe('');});
 it('binds preserve/replace mode to action and rejects invented status or echoed raw data',()=>{expect(ruleAction(action(),1)).toEqual(action());for(const patch of[{status:1},{sort:1},{rule_value:'null'},{spec:[]}])expect(()=>ruleAction({...action(),payload:{...action().payload,...patch}},1)).toThrow();expect(()=>ruleAction(action('create'),1)).toThrow();expect(()=>ruleAction(action(),2)).toThrow();});
 it('requires original strict terminal result while missing receipt remains unknown',()=>{const a=action(),{payload:_,...metadata}=a,result={id:1,created:0,updated:1,count:3,revision:'c'.repeat(64)};expect(ruleReceipt({...metadata,state:'committed',result},a).state).toBe('committed');for(const patch of[{id:2},{updated:0},{created:1}])expect(()=>ruleReceipt({...metadata,state:'committed',result:{...result,...patch}},a)).toThrow();expect(()=>ruleReceipt({...metadata,state:'missing',result},a)).toThrow();});
});

