import { createHash } from 'node:crypto';
import { readAdminProfileThenErrorPagesPredecessor as readFileSync, readAdminProfileThenErrorPagesThenBrowserLogPredecessor as readBrowserLogPredecessor, readAdminProfileThenErrorPagesThenBrowserLogThenConfigClassPredecessor as readBrowserLogThenConfigClassPredecessor } from './helpers/pcBaseAuthorSourceBinding';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { buildAdminProfilePredecessorApiAuditReport as buildAdminFrontendApiAuditReport } from './helpers/pcBaseAuthorSourceBinding';
import { browserLogSourceBinding as proof, reverseBrowserLogSource } from './helpers/browserLogSourceBinding';
import { configClassSourceBinding, reverseConfigClassSource } from './helpers/configClassSourceBinding';
const root=resolve(import.meta.dirname,'../..'),read=(file:string)=>readFileSync(resolve(root,file),'utf8'),sha=(raw:string|Uint8Array)=>createHash('sha256').update(raw).digest('hex');
describe('browser-local log PHP behavior, exact source provenance and unchanged server contracts',()=>{
 for(const entry of proof.sources){
  it(`pins complete actual source and complete predecessor ${entry.file}`,()=>{const current=read(entry.file);expect(sha(current)).toBe(entry.after_sha256);expect(sha(reverseBrowserLogSource(entry.file,current))).toBe(entry.before_sha256);expect(sha(readBrowserLogPredecessor(resolve(root,entry.file)))).toBe(entry.before_sha256);expect(readBrowserLogPredecessor(resolve(root,entry.file),'utf8')).toBe(entry.edits[0]!.before_source);});
  it(`rejects unreviewed, truncated and duplicated source ${entry.file}`,()=>{const raw=read(entry.file);for(const value of [raw+'\n// unreviewed\n',raw.slice(1),raw+raw])expect(()=>reverseBrowserLogSource(entry.file,value)).toThrow();});
  for(const field of ['before_sha256','after_sha256','after_line']as const)it(`rejects forged ${field} ${entry.file}`,()=>{const changed=structuredClone(proof),row=changed.sources.find(r=>r.file===entry.file)!;if(field==='after_line')row.edits[0]!.after_line=2;else row[field]='0'.repeat(64);expect(()=>reverseBrowserLogSource(entry.file,read(entry.file),changed)).toThrow();});
 }
 for(const entry of proof.full_additions)it(`pins complete actual producer or runtime suite ${entry.file}`,()=>expect(sha(read(entry.file))).toBe(entry.sha256));
 for(const [file,hash]of Object.entries({...proof.observed_unchanged,...proof.frozen_predecessor_evidence}))it(`retains accepted source or immutable prior evidence ${file}`,()=>expect(sha(readFileSync(resolve(root,file)))).toBe(hash));
 for(const entry of proof.PHP_sources)it(`retains full fixed PHP original ${entry.file}`,()=>{expect(sha(entry.raw_utf8)).toBe(entry.sha256);expect(new TextEncoder().encode(entry.raw_utf8).length).toBe(entry.bytes);expect(entry.raw_utf8.split('\n').length-(entry.raw_utf8.endsWith('\n')?1:0)).toBe(entry.lines);expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');});
