  it('rejects drift and forged exact-source inverse '+source.file,()=>{const raw=read(source.file);for(const bad of[raw.slice(1),raw+'\n// unreviewed\n',raw+raw])expect(()=>reverseParameterSource(source.file,bad)).toThrow();for(const key of['before_sha256','after_sha256']as const){const forged={...proof,sources:proof.sources.map(row=>row===source?{...row,[key]:'0'.repeat(64)}:row)};expect(()=>reverseParameterSource(source.file,raw,forged)).toThrow();}const forged={...proof,sources:proof.sources.map(row=>row===source?{...row,edits:row.edits.map(edit=>({...edit,after_line:2}))}:row)};expect(()=>reverseParameterSource(source.file,raw,forged)).toThrow();});
  if(proof.predecessor_readports.includes(source.file))it('preserves every old source case and negative fixture '+source.file,()=>{const edit=source.edits[0]!;expect(stripImports(edit.after_source)).toBe(stripImports(edit.before_source));let expected=edit.before_source.replace(/(from\s*['"])\.\/helpers\/ruleSourceBinding(['"])/gu,'$1./helpers/parameterSourceBinding$2');if(source.file.endsWith('/admin-rule-source-binding.test.ts'))expected=expected.replace("import {readFileSync} from 'node:fs';","import {readParameterPredecessor as readFileSync} from './helpers/parameterSourceBinding';").replace("import {buildAdminFrontendApiAuditReport} from '../scripts/admin-frontend-api-audit';","import {buildParameterPredecessorApiAuditReport as buildAdminFrontendApiAuditReport} from './helpers/parameterSourceBinding';");expect(edit.after_source).toBe(expected);expect(edit.after_source).not.toMatch(/from\s*['"]\.\/helpers\/ruleSourceBinding['"]/u);});
 }
 for(const source of proof.full_additions)it('pins full addition '+source.file,()=>{const raw=readFileSync(resolve(root,source.file));expect(raw.length).toBe(source.bytes);expect(sha(raw)).toBe(source.sha256);});
 for(const source of proof.PHP_sources)it('pins whole fixed PHP original '+source.file,()=>{expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');expect(sha(source.raw_utf8)).toBe(source.sha256);expect(Buffer.byteLength(source.raw_utf8)).toBe(source.bytes);expect(source.git_blob).toMatch(/^[a-f0-9]{40}$/u);});
 const frozen=Object.entries(proof.frozen_predecessor_evidence);
 for(let i=0;i<frozen.length;i+=64)it(`preserves immutable predecessor evidence ${i+1}..${Math.min(i+64,frozen.length)}`,()=>{for(const[file,hash]of frozen.slice(i,i+64))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);});
 it('uses real7951 Rule accepted inputs and preserves1727 old proofs/helpers/evidence',()=>{expect(proof.baseline.file_count).toBe(7951);expect(proof.baseline.sha256).toBe('6c3e661b6c584b5a24382e7a7c0f163a4e77b41ce2b18d5a287a2e616358782c');expect(proof.predecessor_readports).toHaveLength(31);expect(new Set(proof.predecessor_readports).size).toBe(31);expect(frozen).toHaveLength(1727);for(const file of['workers-ts/audit/product-rule-author-source-binding-20261026.json','workers-ts/test/helpers/ruleSourceBinding.ts','workers-ts/docs/php-ts-product-rule-author-20261026.md']){expect(proof.sources.some(s=>s.file===file)).toBe(false);expect(sha(read(file))).toBe(proof.frozen_predecessor_evidence[file]);}expect(new Set(proof.sources.map(s=>s.file)).size).toBe(proof.sources.length);expect(new Set(proof.full_additions.map(s=>s.file)).size).toBe(proof.full_additions.length);});
