 it('verifies complete physical manifest origins and actual accepted receipt for both publication images',()=>{const records=proof.predecessor_publication_origins;expect(Object.keys(records).sort()).toEqual(['parameter_before_manifest','rule_accepted_manifest','rule_before_manifest','rule_receipt','rule_validation_manifest']);for(const record of Object.values(records)){expect(sha(record.raw_utf8)).toBe(record.sha256);expect(record.file.startsWith('/')).toBe(true);}const receipt=JSON.parse(records.rule_receipt!.raw_utf8);expect(receipt.status).toBe('accepted');expect(receipt.source_proof_sha256).toBe(sha(read('workers-ts/audit/product-rule-author-source-binding-20261026.json')));expect(records.rule_validation_manifest!.sha256).toBe(receipt.current_source_manifest_sha256);expect(records.rule_before_manifest!.sha256).toBe(receipt.before_manifest_sha256);expect(records.rule_accepted_manifest!.sha256).toBe(receipt.input_manifest_sha256);expect(records.parameter_before_manifest!.sha256).toBe(proof.baseline.sha256);expect(records.parameter_before_manifest!.raw_utf8).toBe(records.rule_accepted_manifest!.raw_utf8);for(const bridge of proof.predecessor_publication){for(const key of['rule_validation_manifest','rule_before_manifest']){const record=(JSON.parse(records[key]!.raw_utf8) as Array<{path:string;sha256:string;bytes:number}>).find(row=>row.path===bridge.file)!;expect(record.sha256).toBe(bridge.validation_sha256);expect(record.bytes).toBe(Buffer.byteLength(bridge.validation_source));}for(const key of['parameter_before_manifest','rule_accepted_manifest']){const record=(JSON.parse(records[key]!.raw_utf8) as Array<{path:string;sha256:string;bytes:number}>).find(row=>row.path===bridge.file)!;expect(record.sha256).toBe(bridge.accepted_sha256);expect(record.bytes).toBe(Buffer.byteLength(bridge.accepted_source));}expect(bridge.validation_origin).toContain('/ensure-author-20261026/inputs/');expect(bridge.accepted_origin).toContain('/rule-author-20261026/inputs/');}});
 it('preserves Rule source-repair metadata without inheriting its seven-gate reuse exception',()=>{const old=JSON.parse(read('workers-ts/audit/product-rule-author-source-binding-20261026.json'));expect(old.source_binding_maintenance).toBeDefined();expect(Object.hasOwn(proof,'source_binding_maintenance')).toBe(false);expect(proof.boundaries.evidence).toContain('not runtime');for(const file of['workers-ts/test/helpers/parameterSourceBinding.ts','workers-ts/audit/product-parameter-author-source-binding-20261026.json','workers-ts/docs/php-ts-product-parameter-author-20261026.md']){expect(proof.sources.some(r=>r.file===file)).toBe(false);expect(proof.full_additions.some(r=>r.file===file)).toBe(false);}});
 it('keeps mature core/Supplier/free-copy/price privileges and three accepted child authors exact',()=>{for(const[file,hash]of Object.entries(proof.observed_unchanged))expect(sha(readFileSync(resolve(root,file))),file).toBe(hash);for(const file of['workers-ts/src/services/admin/AdminProductSpecsService.ts','workers-ts/src/services/product/ProductMetadataService.ts','workers-ts/src/services/product/ProductAssociationService.ts','workers-ts/src/services/supplier/SupplierProductManagementService.ts','workers-ts/src/services/supplier/SupplierProductParameterBindings.ts','workers-ts/src/services/supplier/SupplierProductCopyService.ts','workers-ts/src/migrations/runtimeBusinessPrivilegePlan.ts','view/uniapp-ts/scripts/delivery-workbench-runtime.test.cjs'])expect(Object.hasOwn(proof.observed_unchanged,file)).toBe(true);});
