 for(const entry of proof.sources){
  it(`pins complete actual source and complete predecessor ${entry.file}`,()=>{const current=read(entry.file);expect(sha(current)).toBe(entry.after_sha256);expect(sha(reverseBrowserLogSource(entry.file,current))).toBe(entry.before_sha256);expect(sha(readBrowserLogPredecessor(resolve(root,entry.file)))).toBe(entry.before_sha256);expect(readBrowserLogPredecessor(resolve(root,entry.file),'utf8')).toBe(entry.edits[0]!.before_source);});
  it(`rejects unreviewed, truncated and duplicated source ${entry.file}`,()=>{const raw=read(entry.file);for(const value of [raw+'\n// unreviewed\n',raw.slice(1),raw+raw])expect(()=>reverseBrowserLogSource(entry.file,value)).toThrow();});
  for(const field of ['before_sha256','after_sha256','after_line']as const)it(`rejects forged ${field} ${entry.file}`,()=>{const changed=structuredClone(proof),row=changed.sources.find(r=>r.file===entry.file)!;if(field==='after_line')row.edits[0]!.after_line=2;else row[field]='0'.repeat(64);expect(()=>reverseBrowserLogSource(entry.file,read(entry.file),changed)).toThrow();});
 }
 for(const entry of proof.full_additions)it(`pins complete actual producer or runtime suite ${entry.file}`,()=>expect(sha(read(entry.file))).toBe(entry.sha256));
 for(const [file,hash]of Object.entries({...proof.observed_unchanged,...proof.frozen_predecessor_evidence}))it(`retains accepted source or immutable prior evidence ${file}`,()=>expect(sha(readFileSync(resolve(root,file)))).toBe(hash));
 for(const entry of proof.PHP_sources)it(`retains full fixed PHP original ${entry.file}`,()=>{expect(sha(entry.raw_utf8)).toBe(entry.sha256);expect(new TextEncoder().encode(entry.raw_utf8).length).toBe(entry.bytes);expect(entry.raw_utf8.split('\n').length-(entry.raw_utf8.endsWith('\n')?1:0)).toBe(entry.lines);expect(proof.PHP_ref).toBe('8ed2a5b139f9170dd11b0dff91803f2fd59e40a5');});
 for(const entry of proof.PHP_evidence)it(`pins actual behavior lines ${entry.source}:${entry.start}`,()=>{const source=proof.PHP_sources.find(row=>row.file===entry.source)!;expect(source.raw_utf8.split(/(?<=\n)/u).slice(entry.start-1,entry.end).join('')).toBe(entry.fragment);expect(sha(entry.fragment)).toBe(entry.fragment_sha256);});
 it('retains the exact deterministic API inventory: zero new calls or Worker routes',()=>{const raw=read(proof.current_report.file),report=JSON.parse(raw);expect(sha(raw)).toBe(proof.current_report.sha256);expect(proof.current_report.sha256).toBe('e00f364f4b64fd6eeb308a171bfdd6a0dcfe1e9ea498f359a4151921da8efec3');expect(buildAdminFrontendApiAuditReport()).toEqual(report);expect(report.counts).toEqual({callSites:709,pathVariants:747,registered:747,executable:747,controlledUnavailable:0,unregistered:0,unresolved:0});});
 it('composes only complete browser and config-class predecessor layers',()=>{for(const file of ['view/admin-ts/src/router/index.ts','view/admin-ts/src/layouts/AdminLayout.vue','.github/workflows/workers-runtime-linux.yml']){const previous=reverseBrowserLogSource(file,read(file));expect(readBrowserLogThenConfigClassPredecessor(resolve(root,file),'utf8')).toBe(reverseConfigClassSource(file,previous));const row=configClassSourceBinding.sources.find(row=>row.file===file)!;expect(sha(readBrowserLogThenConfigClassPredecessor(resolve(root,file)))).toBe(row.before_sha256);}expect(reverseBrowserLogSource('other.ts','unaltered')).toBe('unaltered');});
 it('registers authenticated local viewer and exact legacy alias separately from the existing server log',()=>{const router=read('view/admin-ts/src/router/index.ts'),layout=read('view/admin-ts/src/layouts/AdminLayout.vue');expect(router).toContain('path: "system/frontend-log"');expect(router).toContain('alias: "/admin/system/log"');expect(router).toContain('path: "system/log"');expect(router).toContain('component: () => import("@/pages/system/LogList.vue")');expect(layout).toContain('v-if="authStore.isLoggedIn" index="/system/frontend-log"');expect(layout).toContain('v-if="canMenu(\'/system/log\')" index="/system/log"');expect(proof.boundaries.scope).toContain('still open');});
 it('installs before mount and keeps meaningful runtime suites in the actual Admin CI chain',()=>{const main=read('view/admin-ts/src/main.ts'),script=JSON.parse(read('view/admin-ts/package.json')).scripts['test:browser-log'];expect(main.indexOf('installBrowserLog(app, router, useAuthStore(), request);')).toBeLessThan(main.indexOf('app.mount('));for(const file of ['browser-log-model-runtime.test.cjs','browser-log-page-runtime.test.cjs'])expect(script).toContain(file);expect(read('.github/workflows/workers-runtime-linux.yml')).toContain('npm run test:browser-log');expect(read('workers-ts/vitest.config.ts')).toContain('test/*.test.ts');});
});

