      'view/uniapp-ts/scripts/diy-promotion-author-runtime.test.cjs',
      'workers-ts/test/diy-promotion-author-media.test.ts',
    ]);
    expect(parity.sources).toHaveLength(13);
    expect(parity.assets).toEqual([]);
